      hu: ["1356 és 1363 között épült.", "A mameluk építészet remekművének tartják.", "Mind a négy szunnita jogi iskola számára biztosít helyet."],
      ro: ["Construită între 1356 și 1363.", "Considerată o capodoperă a arhitecturii mameluce.", "Include facilități pentru toate cele patru școli de gândire sunnite."],
      en: ["Constructed between 1356 and 1363.", "Considered a masterpiece of Mamluk architecture.", "Includes facilities for all four Sunni schools of thought."],
      es: ["Construida entre 1356 y 1363.", "Considerada una obra maestra de la arquitectura mameluca.", "Ofrece espacios para las cuatro escuelas de jurisprudencia suníes."],
      pt: ["Construída entre 1356 e 1363.", "Considerada uma obra-prima da arquitetura mameluca.", "Oferece espaços para as quatro escolas jurídicas sunitas."],
      fr: ["Construite entre 1356 et 1363.", "Considérée comme un chef-d'œuvre de l'architecture mamelouke.", "Accueille des espaces pour les quatre écoles juridiques sunnites."],
