      es: ["La inauguración tuvo lugar en el año 1960.", "La capacidad máxima es de 75.000 asientos.", "Diseñado por el arquitecto Werner March.", "Sede del Al Ahly y del Zamalek.", "Sede de la final de la Copa de África de 2006.", "Renovación integral en el año 2005."],
