      de: ["Erbaut Mitte des 19. Jahrhunderts.", "Dient normalerweise der Unterbringung von besuchenden Staatsoberhäuptern.", "Verfügt über einen weitläufigen botanischen Garten."],
      hu: ["A 19. század közepén épült.", "Általában látogató államfők fogadására szolgál.", "Kiterjedt botanikus kerttel rendelkezik."],
      ro: ["Construit la mijlocul secolului al XIX-lea.", "De obicei servește la găzduirea șefilor de stat în vizită.", "Prezintă o grădină botanică întinsă."],
