      pt: ["Um dos palácios presidenciais mais magníficos do Egito, inserido em extensos jardins luxuriantes no Cairo.", "Localizado no território da República Árabe do Egito.", "Está ligado ao Nilo ou ao espaço desértico vizinho.", "É marcado pelo clima desértico quente do nordeste da África."],
      fr: ["L'un des palais présidentiels les plus magnifiques d'Égypte, niché dans de vastes jardins luxuriants au Caire.", "Situé sur le territoire de la République arabe d'Égypte.", "En lien avec le Nil ou la zone désertique voisine.", "Marqué par le climat désertique chaud du nord-est de l'Afrique."],
